function Start-TemporaryCleanup {Show-Header;Write-Host "LIMPEZA SEGURA" -ForegroundColor Yellow;Write-Host "Limpa temporarios, Lixeira e cache de download do Windows Update.";if(-not(Confirm-WinOptimizerAction "Iniciar limpeza?")){return};try{@("$env:TEMP\*","$env:LOCALAPPDATA\Temp\*","$env:WINDIR\Temp\*")|ForEach-Object{Remove-Item $_ -Recurse -Force -ErrorAction SilentlyContinue};Clear-RecycleBin -Force -ErrorAction SilentlyContinue;Stop-Service wuauserv,bits -Force -ErrorAction SilentlyContinue;Remove-Item "$env:WINDIR\SoftwareDistribution\Download\*" -Recurse -Force -ErrorAction SilentlyContinue;Start-Service bits,wuauserv -ErrorAction SilentlyContinue;Write-Status "Limpeza concluida." Green;Save-AppliedChange Limpeza "Temporarios" "Temporarios, Lixeira e cache do Update limpos."}catch{Write-Status "Limpeza parcial." Yellow};Pause-WinOptimizer}
function Start-StorageOptimization {Show-Header;Write-Host "DISM STARTCOMPONENTCLEANUP" -ForegroundColor Yellow;Write-Host "Remove componentes substituidos. Nao usa ResetBase.";if(-not(Confirm-WinOptimizerAction "Executar DISM?")){return};Start-Process dism.exe -ArgumentList "/Online","/Cleanup-Image","/StartComponentCleanup" -Wait -NoNewWindow;Write-Status "Processo DISM finalizado." Green;Save-AppliedChange Manutencao "Component cleanup" "DISM StartComponentCleanup executado.";Pause-WinOptimizer}